		["{npc:822}: tame it with the {item:15908}"] = "{npc:822} : apprivoisez-le avec le {item:15908}",
		["{npc:823}, back at the Abbey steps"] = "{npc:823}, de retour au pied des marches de l'abbaye",
		["{npc:894} sells the Shiny Red Apples for the {quest:91736}. Apples looted from kobolds and crates count too: the purchase ticks itself once you have four."] = "{npc:894} vend les Pommes rouges brillantes pour l'{quest:91736}. Les pommes ramassées sur les kobolds et dans les caisses comptent aussi : l'achat se coche tout seul dès que vous en avez quatre.",
		["{npc:911}, the warrior trainer; inside"] = "{npc:911}, le maître des guerriers ; à l'intérieur",
		["{npc:915}, the rogue trainer"] = "{npc:915}, le maître des voleurs",
		["{npc:925}, the paladin trainer"] = "{npc:925}, le maître des paladins",
		["{npc:952}, upstairs"] = "{npc:952}, à l'étage",
		["{npc:955} stands inside the barracks. He has {quest:91738} only while you carry the {item:247824}: talk to him and it goes straight to the hand-in."] = "{npc:955} se tient dans la caserne. Il ne propose {quest:91738} que si vous avez le {item:247824} sur vous : parlez-lui et vous passez directement à la remise.",
		["{npc:955}: he wants your {item:247824}; inside"] = "{npc:955} : il veut votre {item:247824} ; à l'intérieur",
		["{npc:963}: for {npc:234} at {object:81}"] = "{npc:963} : pour {npc:234} au {object:81}",
		["{object:694855} grows in the fields around the vineyards and the Stonefield farm; Stonetusk Boars around them give the blood.\nStonetusk Boars graze between the vineyards and the farm."] = "L'{object:694855} pousse dans les champs autour des vignes et de la ferme des Stonefield ; les Sangliers Brocheroc des environs fournissent le sang.\nLes Sangliers Brocheroc paissent entre les vignes et la ferme.",
		["{quest:76}'s entrance"] = "Entrée de {quest:76}",
		["{quest:87} is inside the Fargodeep Mine, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it."] = "{quest:87} se trouve à l'intérieur de la mine de Fargodeep, pas sur la colline au-dessus : entrez par l'entrée et restez à gauche jusqu'au fond de la mine ; n'empruntez pas les escaliers. Les bandits défias autour des vignobles laissent parfois tomber un {item:1972} : faites un clic droit dessus.",
		["{quest:91733} and {npc:330}"] = "{quest:91733} et {npc:330}",
		["{zone:1429}: kill these as you meet them"] = "{zone:1429} : tuez-les au fur et à mesure",
} end)()
t.guides["groupe-alliance/01-depart-nain"] = (function() return {
		["Amberstill Ranch"] = "Ranch d'Amberstill",
		["Back east through Kharanos: the class quests here wait for level 10."] = "De retour vers l'est par Kharanos : les quêtes de classe ici attendent le niveau 10.",
		["Back through the tunnel to {npc:257597}' cave above the farm."] = "Repassez le tunnel jusqu'à la grotte de {npc:257597}, au-dessus de la ferme.",
		["Back to Anvilmar"] = "Retour à Anvilmar",
		["Back to {npc:257446} in Anvilmar. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "Retournez voir {npc:257446} à Anvilmar. Il vous donne le {item:6635} : prenez le chemin marqué de débris qui monte vers l'ouest depuis le sud de la vallée jusqu'à la Pierre des esprits sur la crête, buvez la Sapta à côté et parlez au {npc:5891}, puis rapportez son {item:6656} à Teo.",
		["Back to {npc:257597}"] = "Retour auprès de {npc:257597}",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls. {zone:1436} is next, west of Goldshire."] = "Retournez voir {npc:6122}. Utilisez l'{item:6928} au cercle d'invocation dans la cave de {object:2164} et vainquez le marcheur du Vide qu'il invoque. {zone:1436} est la suite, à l'ouest de Comté-de-l'Or.",
		["Below ground"] = "Sous terre",
		["Brewnall Village"] = "Village de Brewnall",
		["Brewnall Village sits on the lake west of Kharanos. {npc:8508}'s dock is the first stop; {npc:1374} and {npc:1375} are in the village beyond it."] = "Le Village de Brewnall se trouve sur le lac à l'ouest de Kharanos. Le quai de {npc:8508} est le premier arrêt ; {npc:1374} et {npc:1375} sont dans le village au-delà.",
		["Class trainer"] = "Maître de classe",
		["Coldridge Valley: kill these as you meet them"] = "Vallée de Coldridge : tuez-les au fur et à mesure",
		["Crag Boars and Young Black Bears roam the fields around Kharanos and the depot."] = "Les sangliers des rochers et les jeunes ours noirs errent dans les champs autour de Kharanos et du dépôt.",
		["Deeprun Tram"] = "Tram des profondeurs",
		["Defensive Stance"] = "Posture défensive",
		["Druid trainer"] = "Maître des druides",
		["Each of Grif Wildheart's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him at the Kharanos smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of Kharanos."] = "Chaque quête de Grif Cœur-Sauvage vous donne un {item:15908} : utilisez-le sur la bête qu'il nomme, puis rapportez la baguette à la forge de Kharanos. Les grands sangliers des rochers, léopards des neiges et ours griffeglace errent tous dans les champs juste au sud et à l'est de Kharanos.",
		["Farsen camps on the ridge overlooking the {object:149024} from the west. Talk to him for his farsight."] = "Farsen campe sur la crête surplombant le {object:149024} depuis l'ouest. Parlez-lui pour sa clairvoyance.",
		["Feather Charms, from the Frostmane Novices"] = "Charmes de plume, sur les Novices Frostmane",
		["Firewood"] = "Bois de chauffage",
		["Flintfire's shipments lie on the cave floor, and {npc:278166} is missing somewhere inside.\nCareful: Wendigos stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks from outside avoids this."] = "Les cargaisons de Flintfire gisent au sol de la caverne, et {npc:278166} a disparu quelque part à l'intérieur.\nAttention : les wendigos sont serrés à l'intérieur de la caverne, donc les combats attirent facilement plusieurs ennemis à la fois ; les attirer un par un avec des attaques à distance depuis l'extérieur évite cela.",
		["Follow the road all the way east to the South Gate Outpost at the {zone:1432} tunnel."] = "Suivez la route jusqu'au bout vers l'est jusqu'au Poste de la Porte Sud au tunnel de {zone:1432}.",
		["Follow the road east past the depot to Misty Pine Refuge."] = "Suivez la route vers l'est au-delà du dépôt jusqu'au Refuge des Pins Brumeux.",
		["Follow the road north-east from Kharanos to the depot below the {zone:1455} road."] = "Suivez la route au nord-est depuis Kharanos jusqu'au dépôt sous la route de {zone:1455}.",
		["Follow the road north-east from Kharanos to the depot: the whole east of {zone:1426} is one sweep from here."] = "Suivez la route au nord-est depuis Kharanos jusqu'au dépôt : tout l'est de {zone:1426} se fait en un seul passage depuis ici.",
		["Follow the road through the tunnel and north-east to Kharanos. Start outside: {npc:1252} and Eric's campfire are in front of the Thunderbrew Distillery."] = "Suivez la route à travers le tunnel et au nord-est jusqu'à Kharanos. Commencez à l'extérieur : {npc:1252} et le feu de camp d'Eric sont devant la Distillerie Thunderbrew.",
		["Follow the road up to {zone:1455} and take the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}, {npc:6179} and {npc:6178} on its upper floor: the stairs up start just north-east of {npc:5149}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {zone:1426} drop it, and the Auction House sells it."] = "Suivez la route jusqu'à {zone:1455} et prenez le {object:32362} : {npc:5149}, {npc:6179} et {npc:6178} sont dans le {object:32386}, {npc:6179} et {npc:6178} à l'étage supérieur : l'escalier commence juste au nord-est de {npc:5149}. {npc:6175}, un mendiant, erre dans la ville. Il demande dix {item:2589} : les troggs et trolls de {zone:1426} en laissent tomber, et l'Hôtel des ventes en vend.",
		["Follow the road up to {zone:1455} and train with your class trainer. The Deeprun Tram leaves from {object:171524}, in the east of the city. Ride it to {zone:1453}."] = "Suivez la route jusqu'à {zone:1455} et entraînez-vous avec votre maître de classe. Le Tram des profondeurs part de {object:171524}, à l'est de la ville. Prenez-le pour {zone:1453}.",
		["From the {quest:2997} she gives you"] = "Grâce à {quest:2997} qu'elle vous donne",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "Des Jeunes trolls Frostmane ({npc:706}) peuplent les pentes au sud et à l'est du camp de {npc:786}.",
		["Gnomeregan: kill these as you meet them"] = "Gnomeregan : tuez-les au fur et à mesure que vous les rencontrez",
		["Go through the tunnel into {zone:1432}. Just past it, a path marked by stones climbs the hills on the right of the road north to {npc:257808}'s camp."] = "Traversez le tunnel pour entrer dans {zone:1432}. Juste après, un chemin marqué de pierres gravit les collines à droite de la route vers le nord jusqu'au camp de {npc:257808}.",
		["Gretchen camps just outside the Grizzled Den, the wendigo cave south-west of Kharanos."] = "Gretchen campe juste à l'extérieur de la Tanière Grisonnante, la caverne des wendigos au sud-ouest de Kharanos.",
		["Head back out of {zone:1455} and east along the road to Helm's Bed Lake. {npc:6177} lies dead by its shore: use the {item:6866} on him. The Dark Iron Spies sneaking around the lake carry the script."] = "Sortez de {zone:1455} et allez vers l'est le long de la route jusqu'au Lac du Lit de Helm. {npc:6177} gît mort sur sa rive : utilisez l'{item:6866} sur lui. Les Espions Sombrefer qui rôdent autour du lac portent le script.",
		["Hearth to Thunderbrew Distillery"] = "Pierre de foyer à la Distillerie Tonnerre",
		["Helm's Bed Lake"] = "Lac du Lit de Helm",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "Pendentifs d'ours griffeglace ({item:264356}), sur les Jeunes trolls Frostmane ({npc:706}) des pentes au-dessus du camp",
		["If you skipped {quest:314}, grind here to level 11.6 to stay on the route's plan."] = "Si vous avez passé {quest:314}, tuez des monstres ici jusqu'au niveau 11.6 pour suivre le plan de l'itinéraire.",
		["Inn and flight master"] = "Auberge et maître de vol",
		["Inside Anvilmar"] = "À l'intérieur d'Anvilmar",
		["Instead of walking back up to {zone:1455}, go east through the South Gate tunnel into {zone:1432} and follow the road north to Thelsamar. {npc:1681} stands on the east side of town, past the Stoutlager Inn; his errand pays for a flight back to {zone:1455}."] = "Au lieu de remonter à pied vers {zone:1455}, allez vers l'est par le tunnel de la Porte Sud jusqu'à {zone:1432} et suivez la route vers le nord jusqu'à Thelsamar. {npc:1681} se trouve du côté est de la ville, après l'Auberge de la Bière Brune ; sa commission paye un vol de retour vers {zone:1455}.",
		["Kharanos and the depot"] = "Kharanos et le dépôt",
		["Kill the Crag Boars on the way: their ribs drop before you have {npc:1267}'s quest and count toward it. Back in the distillery: {npc:1699} teaches {skill:185}, then the ribs go to {npc:1267}."] = "Tuez les Sangliers des rochers en chemin : leurs côtes tombent avant que vous ayez la quête de {npc:1267} et comptent pour elle. De retour à la brasserie : {npc:1699} enseigne la {skill:185}, puis les côtes vont à {npc:1267}.",
		["Last: some classes' trainers stand outside"] = "Pour finir : les maîtres de certaines classes se tiennent dehors",
		["Leave {zone:1453} by the main gate, go south to Goldshire and east along the road to the Brackwell Pumpkin Patch. {npc:881} (level 9) stands by its farmhouse."] = "Quittez {zone:1453} par la porte principale, allez au sud jusqu'à Comté-de-l'Or et vers l'est le long de la route jusqu'au Champ de citrouilles de Brackwell. {npc:881} (niveau 9) se tient près de sa ferme.",
		["Leper Gnomes around Brewnall and the Gnomeregan road carry the cogs and gears. Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake."] = "Les gnomes lépreux autour de Brewnall et sur la route de Gnomeregan portent les engrenages et les rouages. Les ours griffeglace, sangliers des rochers anciens et léopards des neiges errent dans les collines autour du lac.",
		["Level 11.6"] = "Niveau 11.6",
		["Level 4 spells, before Gozwin's camp"] = "Sorts du niveau 4, avant le camp de Gozwin",
		["Misty Pine Refuge"] = "Refuge des Pins Brumeux",
		["Misty Pine Refuge: kill these as you meet them"] = "Refuge des Pins Brumeux : tuez-les au fur et à mesure que vous les rencontrez",
		["North Gate Outpost"] = "Poste de la Porte Nord",
		["On the road back west to {zone:1455}."] = "Sur la route du retour vers l'ouest, vers {zone:1455}.",
		["On the way"] = "En chemin",
		["Ragged Young Wolves roam the snow just south of Anvilmar."] = "Jeunes loups hirsutes rodent dans la neige juste au sud d'Anvilmar.",
		["Rockjaw Ambushers by Helm's Bed Lake, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Rockjaw Bonesnappers prowl the quarry and the lake; Dark Iron Spies sneak around the lake shore. One spy drops the {item:274268}."] = "Les Embusqués Mâcheroc au lac du Lit de Helm, au nord de la carrière, et les Brise-dos Mâcheroc plus à l'est laissent tomber le {quest:95214}. Les Croque-os Mâcheroc rodent dans la carrière et le lac ; les Espions Sombrefer rôdent sur la rive du lac. Un espion laisse tomber le {item:274268}.",
		["Rockjaw Skullthumpers fill the quarry; Rockjaw Ambushers by Helm's Bed Lake drop the {item:268548}."] = "Les Brise-crâne Mâcheroc remplissent la carrière ; les Embusqués Mâcheroc au lac du Lit de Helm laissent tomber le {item:268548}.",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of Anvilmar."] = "Les troggs mâcheroc et les troggs mâcheroc costauds fouillent tout le fond de la vallée au sud d'Anvilmar.",
		["Sit by Eric's campfire (type /sit) and wait for the buff."] = "Asseyez-vous près du feu de camp d'Eric (tapez /asseoir) et attendez l'amélioration.",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "Les Petits sangliers des rochers paissent autour du camp de {npc:714} et le long du côté ouest de la vallée.",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "Les Léopards des neiges et les sangliers parcourent la neige entre la ferme et la carrière. Forgerons : les Barres de cuivre s'obtiennent en fondant du {item:2770} ou auprès des marchands d'artisanat.",
		["South Gate Outpost"] = "Poste de la Porte Sud",
		["Start · Dwarf: {zone:1426}"] = "Départ · Nain : {zone:1426}",
		["Steelgrill's Depot"] = "Dépôt de Gaillegrille",
		["Stonesplinter Seers (level 13) stand among the troggs in the south of Stonesplinter Valley, south of {npc:257808}; Tunnel Rat Geomancers (level 12) work the Silver Stream Mine at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time."] = "Les Voyants Casse-pierre (niveau 13) se tiennent parmi les troggs au sud de la Vallée Casse-pierre, au sud de {npc:257808} ; les Géomanciens Rat des tunnels (niveau 12) travaillent à la Mine de Ruisseargent à l'extrémité nord du loch. Les troggs arrivent en groupes et certains lancent à distance : tirez-les un par un.",
		["Subdue the voidwalker"] = "Soumettez le marcheur du Vide",
		["Summon Voidwalker"] = "Invocation d'un marcheur du Vide",
		["Tame Beast"] = "Apprivoiser une bête",
		["Tame {npc:1126}"] = "Apprivoisez {npc:1126}",
		["Tame {npc:1196}"] = "Apprivoisez {npc:1196}",
		["Tame {npc:1201}"] = "Apprivoisez {npc:1201}",
		["The Deeprun Tram"] = "Le Tram des profondeurs",
		["The Fire Spirit Stone"] = "La pierre de l'esprit du feu",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside Anvilmar."] = "Le Mornbrew brûlant dure cinq minutes : allez tout droit au nord vers {npc:836} à l'intérieur d'Anvilmar.",
		["The boars"] = "Les sangliers",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "Le bois de chauffage est dans la neige autour du lac gelé, près du refuge.",
		["The quarry lies just east of Farsen's ridge."] = "La carrière se trouve juste à l'est de la crête de Farsen.",
		["The quarry troggs"] = "Les troggs de la carrière",
		["The three rifles lie in the snow around the frozen lake by the refuge. Minor Ice Elementals drift around the lake and along the way: kill them as you go for {quest:99160}.\nFinish off the Minor Ice Elementals around the small lake just west of the refuge if you are still short."] = "Les trois fusils reposent dans la neige autour du lac gelé près du refuge. Des Élémentaires de glace mineurs dérivent autour du lac et le long du chemin : tuez-les en passant pour {quest:99160}.\nAchevez les Élémentaires de glace mineurs autour du petit lac juste à l'ouest du refuge s'il vous en manque encore.",
		["The tram arrives in the {object:28027}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug."] = "Le tram arrive dans {object:28027}. {npc:5480} entraîne les guerriers dans {object:2100} ; {npc:6089} et {npc:6090} s'y tiennent ensemble près de {object:2152}. {npc:6090} vous affronte pour sa chope.",
		["The troggs"] = "Les troggs",
		["The troll cave"] = "La grotte des trolls",
		["The tunnel"] = "Le tunnel",
		["The {item:2676} grows in baskets up on Shimmer Ridge, the snowy slope north of the road between Kharanos and Brewnall: climb from the road west of Kharanos. The Frostmane Seers camped on the ridge drop it too."] = "Le {item:2676} pousse dans des paniers sur la Crête Scintillante, la pente enneigée au nord de la route entre Kharanos et Brewnall : grimpez depuis la route à l'ouest de Kharanos. Les voyants Crins-de-givre campés sur la crête en font aussi tomber.",
		["The {object:176785} sits next to {npc:271546}, south of the Grizzled Den."] = "Le {object:176785} se trouve à côté de {npc:271546}, au sud de la Tanière Grisonnante.",
		["The {object:269} in the basement"] = "{object:269}, au sous-sol",
		["The {object:270} in the distillery; below ground"] = "Le {object:270} dans la brasserie ; sous terre",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:1388} is a level 12 elite: most classes solo it at level 14, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs avec qui le faire. {npc:1388} est un élite de niveau 12 : la plupart des classes le battent seules au niveau 14, mais vous aurez peut-être besoin d'aide. Passez-le si vous êtes seul : l'itinéraire vous fait regagner l'expérience en tuant des monstres.",
		["Thunderbrew Distillery"] = "Distillerie Thunderbrew",
		["Tram to {zone:1453}"] = "Tram pour {zone:1453}",
		["Upstairs"] = "À l'étage",
		["Use the {item:6866} on {npc:6177}"] = "Utilisez {item:6866} sur {npc:6177}",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Pendant que vous y êtes : apprenez le maniement des bâtons auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; l'arme de mêlée d'un Chasseur vaut surtout par ses caractéristiques, et les armes à deux mains en portent le plus.",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Pendant que vous y êtes : apprenez le maniement des bâtons auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; un bâton apporte plus de caractéristiques de sorts qu'une arme à une main pendant la progression.",
		["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Pendant que vous y êtes : apprenez le maniement des épées auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; une épée en main droite fait progresser un Voleur régulièrement.",
		["While you're here: learn Two-Handed Axes from {npc:11865} ({object:32359}, 10 silver); two-handers level a Paladin fastest."] = "Pendant que vous êtes ici : apprenez Haches à deux mains auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font monter un paladin le plus vite.",
		["While you're here: learn Two-Handed Axes from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "Pendant que vous êtes ici : apprenez Haches à deux mains auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
		["While you're here: learn Two-Handed Maces from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "Pendant que vous êtes ici : apprenez Masses à deux mains auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
		["While you're here: learn Two-Handed Swords from {npc:11867} ({object:2096}, 10 silver); two-handers level a Paladin fastest."] = "Pendant que vous êtes ici : apprenez Épées à deux mains auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; les armes à deux mains font monter un paladin le plus vite.",
		["While you're here: learn Two-Handed Swords from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "Pendant que vous êtes ici : apprenez Épées à deux mains auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
		["You start in front of Anvilmar, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "Vous commencez devant Anvilmar, la salle de pierre au nord de la vallée. {npc:658} attend devant la porte.",
		["Young wolves"] = "Jeunes loups",
		["grind on {npc:260157}"] = "tuez en boucle : {npc:260157}",
		["{item:13850}: the {object:176785}"] = "{item:13850} : {object:176785}",
		["{item:2004}; below ground"] = "{item:2004} ; sous terre",
		["{item:2667}: the meat locker; below ground"] = "{item:2667} : le garde-manger ; sous terre",
		["{item:2686}, from {npc:1247} in the distillery; upstairs"] = "{item:2686}, auprès de {npc:1247} dans la brasserie ; à l'étage",
		["{item:277976}, in the camp"] = "{item:277976}, dans le camp",
