t.guides["groupe-alliance/07-carmines"] = (function() return {
		["Back to Lakeshire"] = "Retour à Comté-du-Lac",
		["Back to {zone:1429}"] = "Retour à {zone:1429}",
		["Blackrock camps"] = "Camps Blackrock",
		["Boat to Stormwind Harbor"] = "Bateau pour le port de Hurlevent",
		["Cross the long bridge north into town. {npc:341} and {npc:382} stand at the north end of the bridge, {npc:900} in the town hall, {npc:381} and {npc:266} on the docks, {npc:343} at the inn, {npc:342} in her garden at the west end."] = "Traversez le long pont vers le nord jusqu'à la ville. {npc:341} et {npc:382} se tiennent au bout nord du pont, {npc:900} dans l'hôtel de ville, {npc:381} et {npc:266} sur les quais, {npc:343} à l'auberge, {npc:342} dans son jardin, à l'ouest.",
		["East past the mill and across the river. Shadowhide gnolls fill the valley; {npc:703} (26, well above you) leads them at its north end: clear his escort first and fight him at full health. Stay out of {object:116} to the south: its orcs are elite.\nCareful: Two gnoll guards stay with him and join the fight whenever he is attacked, even if he has wandered a short way off; other gnolls stand close by and wander through the area."] = "À l'est, passez le moulin et traversez la rivière. Les gnolls ombrepeau remplissent la vallée ; {npc:703} (26, bien au-dessus de vous) les mène à son extrémité nord : éliminez d'abord son escorte et combattez-le à pleine santé. Évitez {object:116} au sud : ses orcs sont élites.\nAttention : Deux gardes gnolls restent avec lui et rejoignent le combat chaque fois qu'il est attaqué, même s'il s'est un peu éloigné ; d'autres gnolls se tiennent à proximité et errent dans la zone.",
		["Fly to {object:81}"] = "Envolez-vous vers {object:81}",
		["Fly to {object:81} and head north-west to the coast: the {object:177790} lies on the sea floor off the shore. Then head east along the road through Elwynn to Redridge."] = "Envolez-vous vers {object:81} et dirigez-vous au nord-ouest vers la côte : {object:177790} gît sur le fond marin au large. Puis suivez la route vers l'est à travers la Forêt d'Elwynn jusqu'aux Carmines.",
		["Follow the road along the south shore of Lake Everstill to the gryphon master. {npc:1070} and {npc:903} stand by the road next to her."] = "Suivez la route le long de la rive sud du lac Placide jusqu'au maître des griffons. {npc:1070} et {npc:903} se tiennent près de la route à côté d'elle.",
		["Galardell Valley: kill these as you meet them"] = "Vallée de Galardell : tuez-les au fur et à mesure",
		["Group 6 · {zone:1433}"] = "Groupe 6 · {zone:1433}",
		["Group: highest player at most 4 levels above the lowest. Above 24? Wait for the others."] = "Groupe : le plus haut au maximum 4 niveaux au-dessus du plus bas. Au-delà de 24 ? Attendre les autres.",
		["Head north out of Lakeshire up the Redridge Canyons to Render's Valley. Blackrock Champions camp in the valley."] = "Sortez au nord de Comté-du-Lac par les canyons des Carmines jusqu'à la vallée de Render. Les champions rochenoires y campent.",
		["Hearth to Lakeshire"] = "Pierre de foyer pour Comté-du-Lac",
		["Inside"] = "À l'intérieur",
		["Keeshan hides at the very north end of the valley, by the {zone:1428} border. Escort him down to Lakeshire; Blackrock orcs ambush you on the way."] = "Keeshan se cache tout au nord de la vallée, près de la frontière de {zone:1428}. Escortez-le jusqu'à Comté-du-Lac ; des orcs rochenoires vous tendent une embuscade en route.",
		["Lake Everstill: kill these as you meet them"] = "lac Placide : tuez-les au fur et à mesure",
		["Lakeridge Highway"] = "Route du Lac",
		["Lakeridge Highway: kill these as you meet them"] = "Route du Lac : tuez-les au fur et à mesure",
		["Lakeshire"] = "Comté-du-Lac",
		["Level 18 and 20 spells"] = "Sorts des niveaux 18 et 20",
		["Murloc Flesheaters and Tidecallers line the south shore east of the bridge. Any of them can carry a {item:1467} or a fin.\nGreater Tarantulas crawl on the slopes around the mill north-east of the lake."] = "Des Dévoreurs murlocs et des Mande-flots murlocs bordent la rive sud à l'est du pont. N'importe lequel peut porter un {item:1467} ou une nageoire.\nDes Grandes tarentules rampent sur les pentes autour du moulin au nord-est du lac.",
		["On the road east, past the Tower of Azora, head north from the bridge to Stone Cairn Lake. {npc:6172} lies south of the lake: use the {item:6866} on him. The Defias Rogue Wizards around him carry the {item:6846}."] = "Sur la route vers l'est, après la tour d'Azora, allez au nord depuis le pont vers le lac de Pierre-Cairn. {npc:6172} se trouve au sud du lac : utilisez {item:6866} sur lui. Les mages voleurs défias autour de lui portent {item:6846}.",
		["On the top floor"] = "Au dernier étage",
		["Only once {quest:97914} is handed in: for {npc:3649}, back in Auberdine (06-ashenvale)"] = "Une fois seulement {quest:97914} remis : pour {npc:3649}, de retour à Auberdine (06-ashenvale)",
		["Redridge Canyons"] = "Canyons des Carmines",
		["Redridge Mongrels and other gnolls hold the hills east of Three Corners, north of the road; Redridge Thrashers prowl among them, Poachers camp south of the road. Redridge Brutes, for the Iron Pikes and Rivets, hold the hills further north; Dire Condors and Great Goretusks roam the hills east of them."] = "Les mongrels des Carmines et d'autres gnolls occupent les collines à l'est des Trois-Cornes, au nord de la route ; les massacreurs des Carmines rôdent parmi eux, les braconniers campent au sud de la route. Les brutes des Carmines, pour les piques en fer et les rivets, tiennent les collines plus au nord ; les condors terribles et les grands goretusks errent sur les collines à l'est d'eux.",
		["Render's Valley"] = "Vallée de Render",
		["Shaman training"] = "Entraînement de chaman",
		["South down the valley's east side to the Blackrock camps east of {object:116}. Renegades, Grunts and Outrunners fill them; keep east of the keep, whose orcs are elite."] = "Descendez au sud le long du flanc est de la vallée vers les camps rochenoires à l'est de {object:116}. Renégats, grunts et coureurs les occupent ; restez à l'est du donjon, dont les orcs sont élites.",
		["Swim east from the bridge into Lake Everstill; the chest lies on the lake bed."] = "Nagez vers l'est depuis le pont dans le lac Placide ; le coffre gît au fond du lac.",
		["The Auberdine boat docks at Stormwind Harbor. Walk up into the city for training and {npc:1646}, then leave by the main gate and follow the road east through {zone:1429}."] = "Le bateau d'Auberdine accoste au port de Hurlevent. Montez en ville pour l'entraînement et {npc:1646}, puis sortez par la porte principale et suivez la route vers l'est à travers {zone:1429}.",
		["The Wanted poster by the inn: {npc:703}, in Galardell Valley"] = "L'affiche de recherche près de l'auberge : {npc:703}, dans la vallée de Galardell",
		["The road from Elwynn enters Redridge at Three Corners. {npc:464} stands where the roads to Redridge and {zone:1431} meet."] = "La route depuis la Forêt d'Elwynn entre dans les Carmines aux Trois-Cornes. {npc:464} se tient là où se rejoignent les routes vers les Carmines et {zone:1431}.",
		["Three Corners"] = "Les Trois-Cornes",
		["Tram to {zone:1455}"] = "Tram pour {zone:1455}",
		["Use the {item:6866} on {npc:6172}"] = "Utilisez le {item:6866} sur {npc:6172}",
		["While you're here: learn Polearms from {npc:11867} ({object:2096}, 1 gold); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Pendant que vous y êtes : apprenez le maniement des armes d'hast auprès de {npc:11867} ({object:2096}, 1 pièce d'or) ; l'arme de mêlée d'un Chasseur vaut surtout par ses caractéristiques, et les armes à deux mains en portent le plus.",
		["While you're here: learn Polearms from {npc:11867} ({object:2096}, 1 gold); two-handers level a Warrior fastest."] = "Pendant que vous y êtes : apprenez le maniement des armes d'hast auprès de {npc:11867} ({object:2096}, 1 pièce d'or) ; les armes à deux mains font progresser un Guerrier le plus vite.",
		["{item:1075}: any Shadowhide gnoll"] = "{item:1075} : tout gnoll Sombrepoil",
		["{item:1309}; underwater"] = "{item:1309} ; sous l'eau",
		["{item:1467} on the way"] = "{item:1467} en chemin",
		["{item:15882}: the {object:177790}"] = "{item:15882} : l'{object:177790}",
		["{item:280911}: Redridge Thrashers"] = "{item:280911} : Vandales des Carmines",
		["{item:6846}: Defias Rogue Wizards"] = "{item:6846} : Sorciers-voleurs défias",
		["{npc:1646}: Thundris' letter from Auberdine"] = "{npc:1646} : Lettre de Thundris depuis Auberdine",
		["{npc:266}, by the docks; upstairs"] = "{npc:266}, près des quais ; à l'étage",
		["{npc:332} is at SI:7 in {object:2100}, {npc:6122} in the {object:2164}'s cellar in the {object:2101}, {npc:376} in the Cathedral of Light."] = "{npc:332} est au SI:7, dans {object:2100}, {npc:6122} dans la cave de {object:2164}, dans {object:2101}, {npc:376} dans la Cathedral of Light.",
		["{npc:332}: {npc:7024} in {zone:1436} takes it, at the end of {zone:1431}"] = "{npc:332} : à rendre à {npc:7024} en {zone:1436}, à la fin de {zone:1431}",
		["{npc:341}: after {quest:89}"] = "{npc:341} : après {quest:89}",
		["{npc:343}, inside"] = "{npc:343}, à l'intérieur",
		["{npc:344}, in the town hall"] = "{npc:344}, dans l'hôtel de ville",
		["{npc:345} (level 24) roots around the pen just west of Lakeshire. Pull him away from the other boars and fight at full health."] = "{npc:345} (niveau 24) fouille autour de l'enclos juste à l'ouest de Comté-du-Lac. Attirez-le loin des autres sangliers et combattez-le à pleine santé.",
		["{npc:349}, below ground"] = "{npc:349}, sous terre",
		["{npc:376}: {npc:11401} in {zone:1457} takes it, later"] = "{npc:376} : à rendre plus tard à {npc:11401}, à {zone:1457}",
		["{npc:376}: {npc:11406} in {zone:1455} takes it, later"] = "{npc:376} : à rendre plus tard à {npc:11406}, à {zone:1455}",
		["{npc:376}: {npc:258785} in {zone:1455} takes it, later"] = "{npc:376} : à rendre plus tard à {npc:258785}, à {zone:1455}",
		["{npc:435}, below ground"] = "{npc:435}, sous terre",
		["{npc:464} walks around Three Corners: look inside the circle on the map"] = "{npc:464} se promène aux Trois-Cornes : regardez à l'intérieur du cercle sur la carte",
		["{npc:6122}: {npc:6244} in the {zone:1413} takes it, later"] = "{npc:6122} : à rendre plus tard à {npc:6244}, dans {zone:1413}",
		["{npc:900}, inside"] = "{npc:900}, à l'intérieur",
		["{npc:903}, by the gryphons south of the bridge"] = "{npc:903}, près des griffons au sud du pont",
		["{zone:1431} is next: follow the road west to Three Corners, then south to Darkshire."] = "{zone:1431} est la suite : suivez la route vers l'ouest jusqu'aux Trois-Cornes, puis au sud jusqu'à Sombre-Comté.",
		["{zone:1453} class quests"] = "Quêtes de classe à {zone:1453}",
		["{zone:1453} flight master"] = "Maître de vol de {zone:1453}",
		["{zone:1453} has no shaman trainer: take the Deeprun Tram from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back."] = "{zone:1453} n'a pas de maître des chamans : prenez le tram des Tréfonds depuis {object:28027} jusqu'à {zone:1455}, entraînez-vous avec {npc:258098}, puis reprenez le tram.",
} end)()
t.guides["groupe-alliance/08-bois-de-la-penombre"] = (function() return {
		["/lay down beside {npc:7207}"] = "/lay down à côté de {npc:7207}",
		["Back to Darkshire"] = "Retour à Sombre-Comté",
		["Brightwood Grove"] = "Bosquet de Bois-clair",
		["Class trainer"] = "Maître de classe",
		["Continue west to {object:102}. The {object:673515} glows by the ruined house south of the road."] = "Continuez vers l'ouest jusqu'à {object:102}. {object:673515} brille près de la maison en ruine au sud de la route.",
		["Darkshire"] = "Sombre-Comté",
		["Every ghoul of the Raven Hill Cemetery's northern half can drop a rib: Flesh Eaters, Bone Chewers, Plague Spreaders and Brain Eaters.\nCareful: A {npc:948} casts Summon Flesh Eating Worms as it dies, which brings extra adds."] = "Chaque goule de la moitié nord du cimetière de la colline aux Corbeaux peut laisser tomber une côte : mangeurs de chair, rongeurs d'os, propagateurs de peste et mangeurs de cervelle.\nAttention : Un {npc:948} lance Invocation de vers mange-chair en mourant, ce qui fait apparaître des renforts.",
		["Fly to {zone:1453}"] = "Prendre un vol pour {zone:1453}",
		["Follow the road north-west past the cemetery to {npc:311}'s camp on the far west edge of the forest. {npc:893} stands beside {npc:311}."] = "Suivez la route vers le nord-ouest après le cimetière jusqu'au camp de {npc:311}, à l'extrême ouest de la forêt. {npc:893} se tient à côté de {npc:311}.",
		["Follow the road south from Three Corners into {zone:1431}; Darkshire lies on the east side of the forest."] = "Suivez la route au sud depuis les Trois-Cornes jusqu'à {zone:1431} ; Sombre-Comté se trouve sur le flanc est de la forêt.",
		["Ghoul Ribs"] = "Côtes de goule",
		["Group 7 · {zone:1431}"] = "Groupe 7 · {zone:1431}",
		["Group: highest player at most 4 levels above the lowest. Above 26? Wait for the others."] = "Groupe : le plus haut au maximum 4 niveaux au-dessus du plus bas. Au-delà de 26 ? Attendre les autres.",
		["Head back east along the road to the Yorgen Farmstead."] = "Revenez vers l'est par la route jusqu'à la ferme des Yorgen.",
		["Head back east to Darkshire."] = "Revenez vers l'est à Sombre-Comté.",
		["Head north through Elwynn to {zone:1453}; Mathias Shaw is at SI:7 in {object:2100}."] = "Remontez vers le nord à travers la forêt d'Elwynn jusqu'à {zone:1453} ; Mathias Shaw se trouve au SI:7, dans {object:2100}.",
		["Head west along the road once more."] = "Repartez une fois de plus vers l'ouest par la route.",
		["Head west along the road out of {object:102} into {zone:1436}. {npc:7024} watches {npc:7053}'s tower from the hills just inside the border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "Prenez la route vers l'ouest hors de {object:102} vers {zone:1436}. {npc:7024} surveille la tour de {npc:7053} depuis les collines juste à l'intérieur de la frontière. Le {npc:7051} (niveau 23) qui garde la tour porte sa clé ; le journal de Klaven est dans le coffre au sommet.",
		["Head west to the hermit once more."] = "Retournez une fois de plus vers l'ouest jusqu'à l'ermite.",
		["Hearth to Darkshire"] = "Pierre de foyer pour Sombre-Comté",
		["Her house stands on the hill south-east of Darkshire, above the Tranquil Gardens Cemetery."] = "Sa maison se dresse sur la colline au sud-est de Sombre-Comté, au-dessus du cimetière des Jardins tranquilles.",
		["Inside"] = "À l'intérieur",
		["Level 22 and 24 spells"] = "Sorts des niveaux 22 et 24",
		["Next: {zone:1453} for training, then the boat from Stormwind Harbor to Auberdine for {zone:1440}."] = "Suivant : {zone:1453} pour l'entraînement, puis le bateau du port de Hurlevent à Auberdine pour {zone:1440}.",
		["No {item:4371} for Look to the Stars? {npc:3133} sells it in the house beside {npc:276}, in limited stock; {npc:1448} in {object:1162} sells it too.\n{npc:276}'s house stands at the east end of town. {npc:3133} sells engineering goods in the house beside it."] = "Pas de {item:4371} pour Regarder les étoiles ? {npc:3133} le vend dans la maison à côté de {npc:276}, en stock limité ; {npc:1448} dans {object:1162} le vend aussi.\nLa maison de {npc:276} se trouve à l'extrémité est de la ville. {npc:3133} vend des articles d'ingénierie dans la maison à côté.",
		["Only if you took the letter after the Ruins of Lordaeron"] = "Seulement si vous avez pris la lettre après les Ruines de Lordaeron",
		["Rabid Dire Wolves roam the woods around the cemetery and {npc:289}, Starving Dire Wolves the hills north-east of him. Pygmy Venom Web Spiders crawl east of the cemetery and drop the venom. Every ghoul of the cemetery's northern half can drop a fang.\nCareful: Wolves and other spider types share the area along the {zone:1436} border, so you can easily pull several mobs at once."] = "Les loups terribles enragés rodent dans les bois autour du cimetière et de {npc:289}, les loups terribles affamés sur les collines au nord-est de lui. Les araignées venimeuses pygmées rampent à l'est du cimetière et laissent tomber le venin. Chaque goule de la moitié nord du cimetière peut laisser tomber une croc.\nAttention : Loups et autres types d'araignées partagent la zone le long de la frontière de {zone:1436}, vous pouvez donc facilement attirer plusieurs monstres à la fois.",
		["Raven Hill Cemetery: kill these as you meet them"] = "Cimetière de la colline aux Corbeaux : tuez-les au fur et à mesure",
		["Rogue training"] = "Entraînement de voleur",
		["Rot Blossoms"] = "Racines pourries ({item:1598})",
		["Shaman training"] = "Entraînement de chaman",
		["Skeletal Horrors walk the hillside between Darkshire and the Tranquil Gardens Cemetery, south-east of town; they drop the Rot Blossoms."] = "Les horreurs squelettiques hantent le flanc de colline entre Sombre-Comté et le cimetière des Jardins tranquilles, au sud-est de la ville ; elles laissent tomber les fleurs de pourriture.",
		["Skeletal Warriors and Skeletal Mages walk among the graves south-east of Darkshire, below {npc:302}'s house on the hill. Every skeleton in {zone:1431} can drop a {item:2378}.\nCareful: Because the skeletons stand near each other, running straight in tends to pull several at once."] = "Les guerriers squelettes et mages squelettes errent parmi les tombes au sud-est de Sombre-Comté, sous la maison de {npc:302} sur la colline. Chaque squelette de {zone:1431} peut laisser tomber {item:2378}.\nAttention : Comme les squelettes sont proches les uns des autres, foncer droit dedans a tendance à en attirer plusieurs à la fois.",
		["The Hushed Bank: kill these as you meet them"] = "La Rive silencieuse : tuez-les au fur et à mesure",
		["The cemetery lies north of the village. Skeletal Horrors and Skeletal Fiends walk its southern half. {npc:522}, an elite, wanders the graves: keep away from him."] = "Le cimetière se trouve au nord du village. Les Squelettes infernaux et les Démons squelettes errent dans sa moitié sud. {npc:522}, un élite, rôde parmi les tombes : tenez-vous à l'écart.",
		["The hermit's shack stands in the woods north-east of the Raven Hill Cemetery."] = "La cabane de l'ermite se trouve dans les bois au nord-est du cimetière de la colline aux Corbeaux.",
		["The mound of loose dirt lies south of the farmhouse, by the old stump."] = "Le monticule de poussière se trouve au sud de la ferme, près de la vieille souche.",
		["Train here, in {zone:1453}, before you go on."] = "Entraînez-vous ici, à {zone:1453}, avant de continuer.",
		["Tram to {zone:1455}"] = "Tram pour {zone:1455}",
		["Tranquil Gardens Cemetery"] = "Cimetière des Jardins tranquilles",
		["Tranquil Gardens Cemetery: kill these as you meet them"] = "Cimetière des Jardins tranquilles : tuez-les au fur et à mesure",
		["Yorgen Farmstead"] = "Ferme des Yorgen",
		["{item:281046}, from the {object:673515}"] = "{item:281046}, sur le {object:673515}",
		["{item:3372}: {npc:1313}, Alchemy Supplies"] = "{item:3372} : {npc:1313}, Fournitures d'alchimie",
		["{item:4371}, from {npc:3133}, if you have none"] = "{item:4371}, chez {npc:3133}, si vous n'en avez pas",
		["{item:4371}, from {npc:3133}: limited stock. Sold out? {npc:1448} in {object:1162} sells it too."] = "{item:4371}, de {npc:3133} : stock limité. Épuisé ? {npc:1448} dans {object:1162} le vend aussi.",
		["{item:7908}, in the chest"] = "{item:7908}, dans le coffre",
		["{npc:202} on the way"] = "{npc:202} en chemin",
		["{npc:2409}, at the north end of town"] = "{npc:2409}, à l'extrémité nord de la ville",
		["{npc:264}, in the town hall"] = "{npc:264}, à l'hôtel de ville",
		["{npc:265}, in her house by the tavern; inside"] = "{npc:265}, dans sa maison près de la taverne ; à l'intérieur",
		["{npc:265}, inside"] = "{npc:265}, à l'intérieur",
		["{npc:267}, in the town hall"] = "{npc:267}, à l'hôtel de ville",
		["{npc:268}, in the house behind the town hall"] = "{npc:268}, dans la maison derrière l'hôtel de ville",
		["{npc:268}, inside"] = "{npc:268}, à l'intérieur",
		["{npc:273}, in the tavern"] = "{npc:273}, dans la taverne",
		["{npc:276}, inside"] = "{npc:276}, à l'intérieur",
		["{npc:288} hides in the house at the west end of {object:102}."] = "{npc:288} se cache dans la maison à l'extrémité ouest de {object:102}.",
		["{npc:332}: Poisons, and {item:18160}"] = "{npc:332} : Poisons, et {item:18160}",
		["{npc:531} on the way"] = "{npc:531} en chemin",
		["{npc:533} on the way"] = "{npc:533} en chemin",
		["{npc:6171}: Redemption"] = "{npc:6171} : Rédemption",
		["{npc:6173} and {npc:6171} are in the Cathedral of Light."] = "{npc:6173} et {npc:6171} sont dans la Cathédrale de la Lumière.",
		["{npc:633}, at the south end of town; inside"] = "{npc:633}, au sud de la ville ; à l'intérieur",
		["{npc:663}, by the town hall"] = "{npc:663}, près de l'hôtel de ville",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}, taverne du Corbeau écarlate",
		["{npc:888} stands south of the road, at the Yorgen Farmstead."] = "{npc:888} se tient au sud de la route, à la ferme des Yorgen.",
		["{object:81} flight master"] = "{object:81} maître de vol",
		["{quest:2607}: {npc:7207}, in the cellar of the Barracks"] = "{quest:2607} : {npc:7207}, dans la cave de la caserne",
		["{quest:337}: a rare drop from {zone:1431}'s mobs"] = "{quest:337} : un butin rare des monstres de {zone:1431}",
		["{zone:1453} has no shaman trainer: take the Deeprun Tram from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the Auberdine boat."] = "{zone:1453} n'a pas de maître des chamans : prenez le tram des Tréfonds depuis {object:28027} jusqu'à {zone:1455}, entraînez-vous avec {npc:258098}, puis reprenez le tram pour le bateau d'Auberdine.",
} end)()
t.guides["groupe-alliance/09-orneval-paluns"] = (function() return {
		["A new {item:279996}, for the four titan watchers around the {zone:1437}; below ground"] = "Une nouvelle {item:279996}, pour les quatre gardiens titans autour des {zone:1437} ; sous terre",
		["Astranaar flight master"] = "Maître de vol d'Astranaar",
		["Auberdine flight master"] = "Maître de vol d'Auberdine",
		["Bathran's Haunt: kill these as you meet them"] = "Hantise de Bathran : tuez-les au passage.",
		["Below ground"] = "Sous terre",
		["Black, Crimson and Monstrous Oozes fill Ironbeard's Tomb, just west of the road to {object:376} and north of Einar's camp. Any ooze there may hold {npc:2111}'s bag.\nMosshide Fenrunners and Mistweavers roam the riverbanks just west and south of {npc:1244}; almost every one drops flint."] = "Gelées noires, cramoisies et monstrueuses remplissent le Tombeau de Barbe-de-fer, juste à l'ouest de la route vers {object:376} et au nord du camp d'Einar. Toute gelée là-bas peut contenir le sac de {npc:2111}.\nCoureurs des brumes et Tisse-brume moussus rodent sur les berges juste à l'ouest et au sud de {npc:1244} ; presque tous laissent du silex.",
		["Boat to {object:1162}"] = "Bateau pour {object:1162}",
		["Cast Teleport: {zone:1450}"] = "Lancez Téléportation : {zone:1450}",
		["Cathedral of Light"] = "Cathédrale de la Lumière",
		["Cave Stalkers and Leech Stalkers fill Thelgen Rock, the cave south-east of the excavation site."] = "Traqueurs des cavernes et Traqueurs sangsues infestent la Roche de Thelgen, la caverne au sud-est du site de fouilles.",
		["Escort Kerlonian to {object:19863} in {zone:1440}."] = "Escortez Kerlonian jusqu'au {object:19863} en {zone:1440}.",
		["Fly to Auberdine"] = "Envolez-vous pour Auberdine",
		["Fly to Rut'theran Village"] = "Envolez-vous vers le village de Rut'theran",
		["Follow the coast north out of Menethil. Bluegill Murlocs fill the marsh; {npc:1259} walks with a pack in the middle of it."] = "Sortez de Menethil en longeant la côte vers le nord. Les Murlocs Branchie-bleue grouillent dans le marais ; {npc:1259} se promène avec un groupe en son milieu.",
		["Follow the coast north to the Zoram Strand. {npc:3846} camps on the beach; Wrathtail nagas fill the shore."] = "Suivez la côte vers le nord jusqu'au Rivage de Zoram. {npc:3846} campe sur la plage ; les nagas Queue-de-rage couvrent le rivage.",
		["Follow the road east to the Howling Vale; {npc:3916} stands by the moonwell.\nThe moonwell lies in the hills north-east of Astranaar."] = "Suivez la route vers l'est jusqu'à la Vallée des Hurlements ; {npc:3916} se tient près du puits de lune.\nLe puits de lune se trouve dans les collines au nord-est d'Astranaar.",
		["Follow the road east. Young Wetlands Crocolisks lurk in the pools north of the excavation site."] = "Suivez la route vers l'est. Des Jeunes crocilisques des Paluns ({npc:1417}) rôdent dans les mares au nord du site de fouilles.",
		["For Bolvar Fordragon in {object:2117}: keep it"] = "Pour Bolvar Fordragon, dans le {object:2117} : gardez-la",
		["For the giant crocolisks of the north coast, on your next visit"] = "Pour les crocilisques géants de la côte nord, lors de votre prochaine visite",
		["For {npc:2228} in Southshore: keep it"] = "Pour {npc:2228} à Rivage-du-Sud : gardez-le",
		["For {npc:2916} in {zone:1455}, at the end of this guide"] = "Pour {npc:2916} à {zone:1455}, à la fin de ce guide",
		["From Stormwind Harbor take the boat to Auberdine; {npc:3649} stands at the north end of the village. Then head south along the road through {zone:1439}."] = "Depuis le port de Hurlevent, prenez le bateau pour Auberdine ; {npc:3649} se tient au bout nord du village. Puis dirigez-vous vers le sud le long de la route à travers {zone:1439}.",
		["Group 8 · {zone:1440}, {zone:1437} & Stonetalon"] = "Groupe 8 · {zone:1440}, {zone:1437} et Les Serres-Rocheuses",
		["Group: highest player at most 4 levels above the lowest. Above 28? Wait for the others."] = "Groupe : le plus haut au maximum 4 niveaux au-dessus du plus bas. Au-delà de 28 ? Attendre les autres.",
		["Head east along the {zone:1437} road, south through {object:1668} into {zone:1432} and west through the tunnel into {zone:1426} to {zone:1455}."] = "Prenez la route de {zone:1437} vers l'est, au sud par {object:1668} vers {zone:1432} et à l'ouest par le tunnel vers {zone:1426} jusqu'à {zone:1455}.",
		["Head south past Mystral Lake into the Talondeep Path tunnel; it comes out in Stonetalon's {object:19555}. {npc:4080} and {npc:4077} camp on the Webwinder Path south-west of the crag."] = "Dirigez-vous au sud en passant le lac Mystral pour entrer dans le tunnel du sentier de Talondeep ; il débouche dans les Serres-Rocheuses au {object:19555}. {npc:4080} et {npc:4077} campent sur le sentier des Tisse-toiles au sud-ouest de la crête.",
		["Head west to the shore of Lake Falathim. Teronis lies among the Saltspittle murlocs; any murloc can drop the {item:5463}."] = "Allez vers l'ouest jusqu'au rivage du lac Falathim. Teronis se trouve parmi les murlocs Crache-sel ; n'importe quel murloc peut laisser tomber le {item:5463}.",
		["Hearth to Astranaar"] = "Pierre de foyer pour Astranaar",
		["Hearth to Deepwater Tavern"] = "Pierre de foyer pour la Taverne des Eaux profondes",
		["Inside"] = "À l'intérieur",
		["Into {zone:1426}"] = "Vers {zone:1426}",
		["Into {zone:1432}"] = "Vers le {zone:1432}",
		["Into {zone:1455}"] = "Vers {zone:1455}",
		["Into {zone:1457}"] = "Vers {zone:1457}",
		["Kerlonian sleeps at the {object:12893} in southern {zone:1439}. Use the {item:13536} to wake him and lead him south along the road into {zone:1440} to {npc:11219} at {object:19863}; blow the horn again whenever he falls asleep.\nCareful: Scripted ambushes of three mobs each attack along the road: furbolgs on the {zone:1439} stretch and undead nearer {object:19863}."] = "Kerlonian dort près du {object:12893} au sud de {zone:1439}. Utilisez le {item:13536} pour le réveiller et conduisez-le vers le sud le long de la route jusqu'en {zone:1440} auprès de {npc:11219} au {object:19863} ; sonnez du cor à nouveau chaque fois qu'il s'endort.\nAttention : Des embuscades scriptées de trois monstres chacune attaquent le long de la route : des furbolgs sur la portion de {zone:1439} et des morts-vivants plus près du {object:19863}.",
		["Kill the elementals for 5 Intact Elemental Bracers, then use the {item:5456}"] = "Tuez les élémentaires pour 5 Bracelets élémentaires intacts ({item:12220}), puis utilisez {item:5456}",
		["Melyria and {npc:3901}"] = "Melyria et {npc:3901}",
		["Menethil"] = "Menethil",
		["Mosshide Gnolls and Mongrels hold the hills south-east of the Green Belt."] = "Les Gnolls Moussus et Molosses moussus tiennent les collines au sud-est de la Ceinture Verte.",
		["Mottled Raptors and Screechers roam the hills west of the excavation site.\nCareful: Once a {npc:1021} drops to 30% health, it calls for help from creatures within 20 yd. Mottled Screechers frequently come in packs of three, and raptors summoned by their calls for help may also join the fight."] = "Des Raptors tachetés et des Hurleurs tachetés parcourent les collines à l'ouest du site de fouilles.\nAttention : quand un {npc:1021} tombe à 30 % de vie, il appelle à l'aide les créatures dans un rayon de 20 m. Les Hurleurs tachetés vont souvent par trois, et les raptors attirés par leurs appels peuvent aussi se joindre au combat.",
		["Mystral Lake"] = "Lac Mystral",
		["Next: fly to Darkshire."] = "Ensuite : volez vers Sombre-Comté.",
		["North of Maestra's Post, plant bundles lie around the ruins of Bathran's Haunt. Dark Strand cultists hold the ruins just south of them: any of them can drop the {item:5366}."] = "Au nord du Poste de Maestra, des fagots de plantes gisent autour des ruines de l'Hantise de Bathran. Des sectateurs de la Brume noire occupent les ruines juste au sud : n'importe lequel peut laisser tomber le {item:5366}.",
		["Only if you looted {quest:337} in {zone:1431}"] = "Seulement si vous avez ramassé {quest:337} à {zone:1431}",
		["Only with {item:5352} from {zone:1439}: {npc:2786}, the {object:32383}"] = "Seulement avec {item:5352} de {zone:1439} : {npc:2786}, {object:32383}",
		["Raptor valley"] = "La vallée des raptors",
		["Red whelps fill the hills west of the gates, Maddened Rotclaws the Green Belt, Razormaws the northern slopes; Neru stands in the north-east (use the {item:279996}).\n{quest:98283} is elite: grouping up is advised.\nFen Creepers hide in the marsh pools north-west of the Green Belt.\nCareful: When out of combat, Fen Creepers cast Sneak from time to time, so they are stealthed and hard to see."] = "Dragonnets rouges infestent les collines à l'ouest des portes, Griffepourris affolés la Ceinture Verte, Gueules-acérées les pentes nord ; Neru se tient au nord-est (utilisez le {item:279996}).\n{quest:98283} est élite : former un groupe est conseillé.\nRôdeurs des marais se cachent dans les mares au nord-ouest de la Ceinture Verte.\nAttention : Hors combat, les Rôdeurs des marais lancent Camouflage par moments, ils sont donc camouflés et difficiles à voir.",
		["Take the Deeprun Tram from {object:171524} to {zone:1453}'s {object:28027}, then walk to the {object:2098}."] = "Prenez le Tram des profondeurs de {object:171524} vers {object:28027} de {zone:1453}, puis marchez jusqu'au {object:2098}.",
		["Take the boat from Stormwind Harbor to Auberdine. Join the two half pendants into the {item:15885} and cast Teleport: {zone:1450}: {npc:11802} is in Nighthaven. Then {npc:11800} in Nighthaven flies Druids straight to Rut'theran Village."] = "Prenez le bateau du port de Hurlevent pour Auberdine. Assemblez les deux demi-pendentifs pour former le {item:15885} et lancez Téléportation : {zone:1450} : {npc:11802} se trouve à Reflet-de-Lune. Ensuite, {npc:11800} à Reflet-de-Lune emmène les druides directement au village de Rut'theran.",
		["Take the portal up to the Cenarion Enclave, then fly back to Auberdine."] = "Prenez le portail menant à l'Enclave cénarienne, puis revenez en vol à Auberdine.",
		["The Bluegill hovels"] = "Les huttes des Branchie-bleue",
		["The Foulweald"] = "Les Vile-sylve",
		["The Foulweald furbolgs live in the woods south of the road, south-east of Astranaar. The Den Watcher and the Ursas guard the den."] = "Les furbolgs Gangrebois vivent dans les bois au sud de la route, au sud-est d'Astranaar. Le Gardien de la tanière et les Ourses gardent la tanière.",
		["The Green Belt"] = "La Ceinture Verte",
		["The Green Belt: kill these as you meet them"] = "Ceinture Verte : tuez-les au fur et à mesure",
		["The Mosshide gnolls"] = "Les gnolls Poil-moussu",
		["The Venture Co. clear the forest of {object:19555}. Loggers and Deforesters work all over it; the Operators run the shredders and one carries the blueprints."] = "La KapitalRisk déboise la forêt de {object:19555}. Bûcherons et Déforestiers y travaillent partout ; les Opérateurs pilotent les déchiqueteuses et l'un d'eux porte les plans.",
		["The Zoram Strand"] = "Le Rivage de Zoram",
		["The bigger raptors hunt in the valley just west of the dig."] = "Les plus gros raptors chassent dans la vallée juste à l'ouest des fouilles.",
		["The excavation site sits on the hill south of the road."] = "Le site de fouilles se trouve sur la colline au sud de la route.",
		["The raptor hills"] = "Les collines des raptors",
		["The tears glow on the small isle east of Astranaar."] = "Les larmes brillent sur la petite île à l'est d'Astranaar.",
		["The two stand together at the western end of the road.\nSouth of the murlocs, {npc:3585} waits at the {object:13352}."] = "Tous deux se tiennent ensemble à l'extrémité ouest de la route.\nAu sud des murlocs, {npc:3585} attend au {object:13352}.",
		["Thelgen Rock"] = "Roche de Thelgen",
		["Three containers in the murloc hovels, south to north: the {object:261}, then the {object:142151}, then the {object:259} at the north end."] = "Trois conteneurs dans les huttes des murlocs, du sud au nord : {object:261}, puis {object:142151}, puis {object:259} à l'extrémité nord.",
		["Timber and iron piles lie around the keep and along the harbor's walls."] = "Des piles de bois et de fer sont éparpillées autour du donjon et le long des murs du port.",
		["To {object:1162}"] = "Vers {object:1162}",
		["Tram to {zone:1453}"] = "Tram pour {zone:1453}",
		["Underwater"] = "Sous l'eau",
		["Webwinder Path"] = "Sentier des Tisse-toiles",
		["West of Mystral Lake, the stardust bushes grow among the ruins."] = "À l'ouest du Lac Mystral, les buissons couverts de poussière d'étoile poussent parmi les ruines.",
		["Whelgar's Excavation Site"] = "Site de fouilles de Whelgar",
		["While you're here: learn Two-Handed Axes from {npc:11865} ({object:32359}, 10 silver); two-handers level a Paladin fastest."] = "Pendant que vous êtes ici : apprenez Haches à deux mains auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font monter un paladin le plus vite.",
		["While you're here: learn Two-Handed Axes from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "Pendant que vous êtes ici : apprenez Haches à deux mains auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
		["While you're here: learn Two-Handed Maces from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "Pendant que vous êtes ici : apprenez Masses à deux mains auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
		["Young crocolisks"] = "Jeunes crocilisques",
		["{item:15885}: join the two halves"] = "{item:15885} : assemblez les deux moitiés",
		["{item:3349} on the way"] = "{item:3349} en chemin",
		["{item:5424}, in the ruins on the shore"] = "{item:5424}, dans les ruines du rivage",
		["{npc:1076}, below ground"] = "{npc:1076}, sous terre",
		["{npc:11406} and {npc:258785} are in the {object:32386}, in the {object:32362}."] = "{npc:11406} et {npc:258785} sont dans le {object:32386}, dans {object:32362}.",
		["{npc:11406}: Chastise"] = "{npc:11406} : Châtier",
		["{npc:1217}, upstairs in the inn"] = "{npc:1217}, à l'étage de l'auberge",
		["{npc:1239}, in the inn"] = "{npc:1239}, à l'auberge",
		["{npc:1242}, on the pier north of the inn"] = "{npc:1242}, sur la jetée au nord de l'auberge",
		["{npc:1242}: for {npc:2104} in the keep"] = "{npc:1242} : pour {npc:2104}, dans le donjon",
		["{npc:1244}: {quest:98283}, an elite raptor"] = "{npc:1244} : {quest:98283}, un raptor élite",
		["{npc:1440}, in the Royal Library"] = "{npc:1440}, dans la Bibliothèque royale",
		["{npc:1444}, in the {object:2098}"] = "{npc:1444}, sur la {object:2098}",
		["{npc:1480}, inside"] = "{npc:1480}, à l'intérieur",
		["{npc:1573}, in the {object:32372}"] = "{npc:1573}, à {object:32372}",
		["{npc:2086}, by the keep; inside"] = "{npc:2086}, près du donjon ; à l'intérieur",
		["{npc:2092}'s quest in {zone:1455} needs level 28. If you are short of it after these hand-ins, grind the Dragonmaw orcs at the camps along the road east to {object:1668} before you go on."] = "La quête de {npc:2092} en {zone:1455} requiert le niveau 28. S'il vous manque après ces remises, farmez les orcs Gueule-de-dragon aux camps le long de la route à l'est vers {object:1668} avant de continuer.",
		["{npc:2093} camps by the road; {npc:1244} stands farther east, by the river."] = "{npc:2093} campe au bord de la route ; {npc:1244} se tient plus à l'est, près de la rivière.",
		["{npc:2094} stands by the north gate."] = "{npc:2094} se tient près de la porte nord.",
		["{npc:2094}, by the north gate"] = "{npc:2094}, près de la porte nord",
		["{npc:2096}, by the north gate"] = "{npc:2096}, près de la porte nord",
		["{npc:2096}: he won't offer 305 while you carry it"] = "{npc:2096} : il ne propose pas la 305 tant que vous l'avez sur vous",
		["{npc:2097}, by the north gate"] = "{npc:2097}, près de la porte nord",
		["{npc:2104}, by the keep"] = "{npc:2104}, près du donjon",
		["{npc:2104}, on the top floor"] = "{npc:2104}, au dernier étage",
		["{npc:210995} may not offer these to every class; if he doesn't, carry on.; walks around The Talondeep Path: the map marks where to look"] = "{npc:210995} ne propose pas forcément ces quêtes à toutes les classes ; s'il ne le fait pas, continuez. ; se promène autour du Sentier de Talondeep : la carte indique où chercher",
		["{npc:3649}: Alexston's reply, if you took it in {zone:1453}"] = "{npc:3649} : la réponse d'Alexston, si vous l'avez prise à {zone:1453}",
		["{npc:3664} and his voidwalkers hold the Ruins of Ordil'Aran south of the shrine. Pull his guards first."] = "{npc:3664} et ses marcheurs du Vide occupent les ruines d'Ordil'Aran au sud du sanctuaire. Tirez d'abord ses gardes.",
		["{npc:3691}, in the inn"] = "{npc:3691}, à l'auberge",
		["{npc:3885} stands at the Silverwind Refuge on the east shore of Mystral Lake; {npc:210995} camps on its west shore. Befouled Water Elementals wade in the lake between them."] = "{npc:3885} se trouve au Refuge de Brise-argent sur la rive est du lac Mystral ; {npc:210995} campe sur la rive ouest. Des élémentaires d'eau souillés pataugent dans le lac entre eux.",
		["{npc:3894}, inside"] = "{npc:3894}, à l'intérieur",
		["{npc:3970}: for {npc:1480} in Menethil, at the end of this guide; inside"] = "{npc:3970} : pour {npc:1480} à Menethil, à la fin de ce guide ; à l'intérieur",
		["{npc:3987} (25) leads the Thistlefur furbolgs at the camp north of Astranaar. Clear his guards first, one at a time.\nCareful: The furbolgs near him usually join in when he is pulled. Killing the ones along his path first lets you fight him alone."] = "{npc:3987} (25) dirige les furbolgs Chardon-vert au camp au nord d'Astranaar. Éliminez d'abord ses gardes, un par un.\nAttention : Les furbolgs près de lui se joignent généralement au combat quand il est tiré. Tuer ceux le long de son chemin d'abord vous permet de l'affronter seul.",
		["{npc:4201}, in the hut north of them; inside"] = "{npc:4201}, dans la hutte au nord ; à l'intérieur",
		["{npc:4201}, inside"] = "{npc:4201}, à l'intérieur",
		["{npc:4276} mines in the Windshear Mine at the east end of the crag. Talk to him and fend off the Venture Co. raiders while he mines.\nCareful: The kobolds arrive in waves. The first wave is melee fighters, and the second adds casters to the mix. Regular mobs in the mine respawn quickly and can join the fight while the waves are coming. A group is recommended."] = "{npc:4276} mine dans la mine de Tranchevent à l'extrémité est de la crête. Parlez-lui et repoussez les raiders de la Compagnie des eaux de Sombrivage pendant qu'il mine.\nAttention : Les kobolds arrivent par vagues. La première vague est composée de combattants au corps à corps, et la seconde ajoute des lanceurs de sorts. Les mobs normaux de la mine réapparaissent rapidement et peuvent se joindre au combat pendant l'arrivée des vagues. Un groupe est recommandé.",
		["{npc:482}, the cheese shop in the {object:2096}"] = "{npc:482}, la fromagerie du {object:2096}",
		["{npc:4959} and {npc:482}"] = "{npc:4959} et {npc:482}",
		["{npc:4982}, in the Cathedral of Light"] = "{npc:4982}, dans la Cathédrale de la Lumière",
		["{npc:5082}, Mikhail and Tapoke Jahn are all at Menethil's inn; Tapoke fights you when you talk to Mikhail, but gives up once beaten. {npc:1480} stands a short walk north-east of the inn.\n{npc:2104} stands in Menethil Keep, a short walk from {npc:1242}.\n{npc:2104} stands in Menethil Keep."] = "{npc:5082}, Mikhail et Tapoke Jahn sont tous à l'auberge de Menethil ; Tapoke vous attaque quand vous parlez à Mikhail, mais se rend une fois vaincu. {npc:1480} se tient à quelques pas au nord-est de l'auberge.\n{npc:2104} se trouve au Donjon de Menethil, à quelques pas de {npc:1242}.\n{npc:2104} se trouve au Donjon de Menethil.",
		["{object:176634}, beside him"] = "{object:176634}, à côté de lui",
		["{object:19555}: kill these as you meet them"] = "{object:19555} : tuez-les au fur et à mesure.",
		["{object:2164} is in the {object:2101}."] = "{object:2164} se trouve dans le {object:2101}.",
		["{quest:1009} walks the northern tip of the Zoram Strand with Wrathtail guards."] = "{quest:1009} arpente l'extrémité nord du Rivage de Zoram avec des gardes Queue-de-rage.",
		["{quest:1010}, from the plant bundles"] = "{quest:1010}, sur les bottes de plantes",
		["{zone:1437}: kill these as you meet them"] = "{zone:1437} : tuez-les au passage",
		["{zone:1455} priests"] = "Prêtres d'{zone:1455}",
} end)()
